package platform.contentapi.execution;

import java.nio.file.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import platform.contentapi.management.SourceJson;
import tools.jackson.databind.JsonNode;

/** Explicit test-only internal capability; production WorkerExecutionCapability remains unchanged. */
public final class RssContentTestSupport {
    private RssContentTestSupport(){}
    public record Completed(UUID artifact,WorkerRepository.Session session,byte[] evidence){}
    @FunctionalInterface public interface Fault {void at(String phase,String point,WorkerRepository.Owner owner);}
    public static Completed execute(JdbcTemplate j,ManagementTransactions t,WorkerRepository w,InstallationHostGuard g,WorkerRepository.Owner o,String runtime,Fault f){var r=new RssContentExecution(j,t,w,(phase,point,owner)->f.at(phase,point.name(),owner)).execute(g,o,runtime);return new Completed(r.artifact(),r.session(),r.evidence());}
    public static UUID inspect(JdbcTemplate j,ManagementTransactions t,WorkerRepository w,InstallationHostGuard g,UUID run,String runtime){return new RssContentExecution(j,t,w).inspect(g,run,runtime);}
    public static JsonNode modules(Path root)throws Exception{var n=SourceJson.object();for(String m:RssContentRuntime.MODULES)n.put(m,SourceJson.sha(Files.readAllBytes(root.resolve(m))));return n;}
    /** Synthetic metadata only: exercises SQL fencing/atomicity, never asserts native qualification. */
    public record Fence(Object stage,JsonNode frozen,JsonNode gold,JsonNode reference,byte[] artifact){}
    public static Fence seed(JdbcTemplate j,WorkerRepository w,InstallationHostGuard g,WorkerRepository.Owner owner){return seed(j,w,g,owner,null);}
    public static Fence seed(JdbcTemplate j,WorkerRepository w,InstallationHostGuard g,WorkerRepository.Owner owner,String stop){
        var frozen=w.frozenContent(g,owner);var reference=RssContentInputs.reference(frozen);UUID silver=UUID.randomUUID(),goldId=UUID.randomUUID();String sha="a".repeat(64),fp="b".repeat(64);var q=SourceJson.object();q.putObject("selection").put("storageBindingId","50000000-0000-4000-8000-000000000003").put("relativeAddress","fixture/silver");q.putObject("verification").putObject("inventoryIdentity").put("sha256",sha);byte[] qb=SourceJson.canonical(q);
        j.update("INSERT INTO ddip_management.artifacts(artifact_id,kind,product_id,contract_version,processor_revision,native_identity,storage_binding_id,relative_address,evidence_bytes,evidence_sha256,verified_at) VALUES (?,'SILVER','content-intelligence',1,1,?,'50000000-0000-4000-8000-000000000003','fixture/silver',?,?,clock_timestamp())",silver,sha,qb,SourceJson.sha(qb));
        byte[] receipt=SourceJson.canonical(SourceJson.object());String source=frozen.get("sources").get(0).get("sourceId").stringValue();j.update("INSERT INTO ddip_management.rss_deliveries(run_id,source_id,revision,owning_attempt_id,journal_address,journal_descriptor,journal_sha256,ingestion_id,original_ingested_at_text,expected_evidence,expected_sha256,payload_length,payload_sha256,state,metadata_sha256,receipt_bytes) VALUES (?,?,?,?,'fixture/journal',?,?,?,'2026-10-30T00:00:00Z',?,?,0,?,'BRONZE_VERIFIED',?,?)",owner.runId(),source,frozen.get("sources").get(0).get("revision").intValue(),owner.attemptId(),receipt,SourceJson.sha(receipt),UUID.randomUUID(),receipt,SourceJson.sha(receipt),sha,sha,receipt);
        for(String phase:List.of("FETCH_SOURCE","STORE_BRONZE","SILVER","PREPARE_GOLD","PUBLISH_GOLD")){if("MISSING_FETCH".equals(stop) && phase.equals("FETCH_SOURCE"))continue;j.update("INSERT INTO ddip_management.stage_invocations(attempt_id,stage,item_ordinal,checkpoint_id,state,input_evidence_sha256,finished_at) VALUES (?,?,0,?,'VERIFIED',?,clock_timestamp())",owner.attemptId(),phase,UUID.randomUUID(),sha);}
        j.update("INSERT INTO ddip_management.stage_artifacts VALUES (?,'SILVER',0,'RESULT',0,?)",owner.attemptId(),silver);
        var gold=SourceJson.object().put("artifactId",goldId.toString());var a=SourceJson.object().put("nativeFingerprint",fp).put("storageBindingId","content-GOLD").put("relativeAddress","fixture/gold");a.putArray("inputs").addObject().put("artifactId",silver.toString());byte[] ab=SourceJson.canonical(a);gold.set("artifact",a);gold.put("evidenceSha256",SourceJson.sha(ab));var input=gold.putObject("command").putArray("inputs").addObject().put("artifactId",silver.toString()).put("originRunId",owner.runId().toString()).put("sourceId",source);input.set("qualification",q);input.set("receipt",SourceJson.parse(receipt));
        j.update("INSERT INTO ddip_management.artifacts(artifact_id,kind,product_id,contract_version,processor_revision,native_identity,storage_binding_id,relative_address,evidence_bytes,evidence_sha256,verified_at) VALUES (?,'GOLD','content-intelligence',1,1,?,'content-GOLD','fixture/gold',?,?,clock_timestamp())",goldId,fp,ab,SourceJson.sha(ab));j.update("INSERT INTO ddip_management.artifact_dependencies VALUES (?,'SILVER',0,?)",goldId,silver);j.update("INSERT INTO ddip_management.stage_artifacts VALUES (?,'PUBLISH_GOLD',0,'RESULT',0,?)",owner.attemptId(),goldId);
        String inputs=SourceJson.sha(SourceJson.canonical(RssContentInputs.dependencies(gold,reference)));var check=w.beginContent(g,owner,"CHECK_INPUTS",UUID.randomUUID(),sha,inputs,inputs,frozen,gold,reference);check=w.authorizePublication(g,check);check=w.recordPublicationChild(g,check,new InstallationHostGuard.ProcessIdentity(UUID.randomUUID(),ProcessHandle.current().pid(),ProcessHandle.current().info().startInstant().orElseThrow()));w.checkpointContent(g,check,sha,frozen,gold,reference);owner=check.owner();var publish=w.beginContent(g,owner,"PUBLISH_CONTENT",UUID.randomUUID(),sha,inputs,fp,frozen,gold,reference);publish=w.authorizePublication(g,publish);if("PUBLISH_CONTENT".equals(stop))return new Fence(publish,frozen,gold,reference,new byte[0]);publish=w.recordPublicationChild(g,publish,new InstallationHostGuard.ProcessIdentity(UUID.randomUUID(),ProcessHandle.current().pid(),ProcessHandle.current().info().startInstant().orElseThrow()));w.checkpointContent(g,publish,sha,frozen,gold,reference);
        var stage=w.beginContent(g,publish.owner(),"VERIFY_RESULT",UUID.randomUUID(),sha,inputs,fp,frozen,gold,reference);stage=w.authorizePublication(g,stage);if("VERIFY_RESULT".equals(stop))return new Fence(stage,frozen,gold,reference,new byte[0]);stage=w.recordPublicationChild(g,stage,new InstallationHostGuard.ProcessIdentity(UUID.randomUUID(),ProcessHandle.current().pid(),ProcessHandle.current().info().startInstant().orElseThrow()));var e=SourceJson.object().put("kind","CONTENT").put("productId","content-intelligence").put("contractVersion",1).put("processorRevision",1).put("nativeFingerprint",fp).put("storageBindingId","content-CONTENT").put("relativeAddress","v1/processor_revision=1/publication="+fp);e.set("inputs",RssContentInputs.dependencies(gold,reference));var v=e.putObject("verification").put("status","VERIFIED");v.putObject("prepared").put("fingerprint",fp);v.putObject("completion").putObject("output_counts").put("content_catalog_v1",1).put("content_source_discovery_daily_v1",1);return new Fence(stage,frozen,gold,reference,SourceJson.canonical(e));
    }
    public static UUID finish(JdbcTemplate j,WorkerRepository w,InstallationHostGuard g,Fence f){return w.succeedContent(g,(WorkerRepository.PublicationStage)f.stage(),"c".repeat(64),f.artifact(),f.frozen(),f.gold(),f.reference());}
    public static void check(WorkerRepository w,InstallationHostGuard g,Fence f){w.checkPublication(g,(WorkerRepository.PublicationStage)f.stage());}
    public static void authorizeAgain(WorkerRepository w,InstallationHostGuard g,Fence f){w.authorizePublication(g,(WorkerRepository.PublicationStage)f.stage());}
    public static void ambiguous(WorkerRepository w,InstallationHostGuard g,Fence f){w.blockPublication(g,(WorkerRepository.PublicationStage)f.stage(),false);}
    public static void cleanLaunchFailure(WorkerRepository w,InstallationHostGuard g,Fence f){w.blockPublication(g,(WorkerRepository.PublicationStage)f.stage(),true);}
}
